const savedTheme=localStorage.getItem("theme"),systemPrefersDark=window.matchMedia("(prefers-color-scheme: dark)").matches,theme=savedTheme?savedTheme:systemPrefersDark?"dark":"light";document.documentElement.setAttribute("data-theme",theme),document.getElementById("theme-toggle").addEventListener("click",()=>{console.log("test");const e=document.documentElement.dataTheme==="dark"?"light":"dark";document.documentElement.dataTheme=e,localStorage.setItem("theme",e)})